# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student

def make_student(last, first, section="A", email="x@y.edu"):
    return Student("1", last, first, section, email)

class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        rows = contact_rows([
            make_student("Varrow", "Ines"),
            make_student("Thistle", "Bram"),
        ])
        self.assertTrue(rows[0].startswith("Thistle, Bram"))
        self.assertTrue(rows[1].startswith("Varrow, Ines"))

    def test_columns_line_up(self):
        person = make_student("Li", "Al", "B", "a@y.edu")
        expected = "Li, Al               B        a@y.edu"
        self.assertEqual(contact_rows([person]), [expected])

    def test_missing_email_names_student(self):
        people = [make_student("Quill", "Sefa", email=None)]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(people)
        self.assertIn("Quill, Sefa", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        people = [make_student("Quill", "Sefa", email=" ")]
        with self.assertRaises(ProjectError):
            contact_rows(people)

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
